//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// BASIC HELPERS
//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

function cleanNumber(value) {
  if (value === undefined || value === null) return '';

  const str = String(value)
    .replace(/\$/g, '')
    .replace(/,/g, '')
    .replace(/\+/g, '')
    .trim();

  const n = Number(str);
  return Number.isFinite(n) ? n : '';
}

function extract(regex, text) {
  const match = text.match(regex);
  return match ? match[1].trim() : '';
}

function normalizeSymbol(symbol) {
  const raw = String(symbol || '').trim().toUpperCase();
  if (!raw) return '';

  // TradingView can send symbols as NFLX or NASDAQ:NFLX.
  // For matching Google Sheets rows, both must be treated as the same symbol.
  const parts = raw.split(':');
  return parts[parts.length - 1];
}

function normalizeTradeId(tradeId) {
  const raw = String(tradeId || '').trim().toUpperCase();
  if (!raw) return '';
  if (raw.startsWith('VIXALE_EDGE:')) return raw;

  const match = raw.match(/^(.*)_(LONG|SHORT)$/);
  if (!match) {
    return raw.includes(':') ? raw.replace(/^.*:/, '') : raw;
  }

  return `${normalizeSymbol(match[1])}_${match[2]}`;
}

function makeTradeId(symbol, side) {
  const cleanSymbol = normalizeSymbol(symbol);
  const cleanSide = String(side || '').trim().toUpperCase();

  if (!cleanSymbol || !cleanSide) return '';
  return `${cleanSymbol}_${cleanSide}`;
}

function isV51IntradayName(value) {
  const text = String(value || '').toUpperCase();
  return text.includes('VX_ST_STK_INTRADAY_V51') || text.includes('ST_STOP_ATR_TARGET_WFO') || text.includes('_INTRADAY');
}

function isV51IntradayRow(row) {
  if (!row) return false;
  return isV51IntradayName(row.strategy) || isV51IntradayName(row.profile) || isV51IntradayName(row.raw);
}

function isFionaLimitPullbackName(value) {
  const text = String(value || '').toUpperCase();
  return text.includes('FIONA_LIMIT_PULLBACK_ATR_TARGET') ||
    text.includes('VX_FIONA_LIMIT_PULLBACK_LIVE') ||
    text.includes('_FIONA_LIMIT') ||
    text.includes('FIONA_LONG_LIMIT_PULLBACK') ||
    text.includes('FIONA_SHORT_LIMIT_PULLBACK');
}

function isFionaLimitPullbackRow(row) {
  if (!row) return false;
  return isFionaLimitPullbackName(row.strategy) ||
    isFionaLimitPullbackName(row.profile) ||
    isFionaLimitPullbackName(row.variant) ||
    isFionaLimitPullbackName(row.reason) ||
    isFionaLimitPullbackName(row.raw);
}

function isVixaleEdgePendingLifecycleRow(row) {
  if (!row) return false;
  return String(row.system_id || '').toUpperCase() === 'VIXALE_EDGE' &&
    isFionaLimitPullbackRow(row);
}

function isVixaleEdgePendingCancel(row) {
  return isVixaleEdgePendingLifecycleRow(row) &&
    String(row.cancel_scope || '').toUpperCase() === 'PENDING_ONLY' &&
    Boolean(row.setup_id);
}

function isOppositeFlipName(value) {
  const text = String(value || '').toUpperCase();
  return text.includes('SHREK_1_4') ||
    text.includes('VX_ST_OPPOSITE_FLIP_ALWAYS_IN_MARKET') ||
    text.includes('OPPOSITE_FLIP_ALWAYS_IN_MARKET') ||
    text.includes('NONE_OPPOSITE_FLIP');
}

function isOppositeFlipRow(row) {
  if (!row) return false;
  return isOppositeFlipName(row.strategy) ||
    isOppositeFlipName(row.profile) ||
    isOppositeFlipName(row.variant) ||
    isOppositeFlipName(row.target_type) ||
    isOppositeFlipName(row.reason) ||
    isOppositeFlipName(row.raw);
}

function publicSystemLabelFromRaw(...rawValues) {
  const joined = rawValues.map(value => String(value || '')).join('\n');

  // Public naming must preserve the same precedence as internal classification:
  // Fiona-specific markers are checked before generic Opposite Flip / Shrek markers.
  if (isFionaLimitPullbackName(joined)) return 'Vixale Edge';
  if (
    isOppositeFlipName(joined) ||
    joined.toUpperCase().includes('FIONA_PULLBACK_HTF_ATR_TARGET') ||
    /\bSHREK\b/i.test(joined)
  ) {
    return 'Vixale Prime';
  }
  if (/\bFIONA\b/i.test(joined)) return 'Vixale Edge';

  return '';
}

function publicExitLabel(value) {
  const text = String(value || '').trim();
  const normalized = text.toUpperCase().replace(/[_-]+/g, ' ');

  if (
    normalized === 'CLOSE STOP' ||
    normalized === 'FLIP CLOSE' ||
    (normalized.includes('OPPOSITE') && normalized.includes('FLIP'))
  ) {
    return 'Stop Loss';
  }

  return text;
}

function isEmaPullbackName(value) {
  const text = String(value || '').toUpperCase();
  return text.includes('VX_EMA_CROSS_PULLBACK_ATR_TARGET') ||
    text.includes('EMA_CROSS_PULLBACK_ATR_TARGET') ||
    text.includes('EMA_CROSS_PULLBACK');
}

function isEmaPullbackRow(row) {
  if (!row) return false;
  return isEmaPullbackName(row.strategy) ||
    isEmaPullbackName(row.profile) ||
    isEmaPullbackName(row.variant) ||
    isEmaPullbackName(row.reason) ||
    isEmaPullbackName(row.raw);
}

function isOpenOnSetupRow(row) {
  return isV51IntradayRow(row) || isOppositeFlipRow(row) || isEmaPullbackRow(row);
}

function isNoTargetMode(rowOrPayload) {
  if (!rowOrPayload) return false;

  const targetType = String(rowOrPayload.target_type || rowOrPayload.targetType || '').toUpperCase();
  const variant = String(rowOrPayload.variant || '').toUpperCase();

  // Shrek can now run in two live modes:
  // 1) NONE_OPPOSITE_FLIP / no target
  // 2) ATR_LIMIT_OPPOSITE_FLIP / attached TWS target
  // Do NOT treat every Shrek/OppositeFlip payload as no-target anymore.
  return targetType === 'NONE' ||
    targetType === 'NO_TARGET' ||
    targetType.includes('NONE_OPPOSITE_FLIP') ||
    variant.includes('OPPOSITE_FLIP_ALWAYS_IN_MARKET');
}

function sheetEventLabel(row) {
  const event = String(row?.event || '').toUpperCase();
  const rawEvent = String(row?.raw_event || '').toUpperCase();

  // Opposite Flip uses CLOSE_STOP only as a normal reversal/flip exit.
  // Keep internal event as SL for bridge-forward compatibility and store the
  // backward-compatible Sheets label; public surfaces map it to Stop Loss.
  if (isOppositeFlipRow(row) && event === 'SL' && rawEvent === 'CLOSE_STOP') {
    return 'FLIP_CLOSE';
  }

  return event;
}

function nowNy() {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(new Date());

  const get = type => parts.find(p => p.type === type)?.value || '';

  return `${get('year')}-${get('month')}-${get('day')} ${get('hour')}:${get('minute')}:${get('second')}`;
}

function formatNyTimeFromMs(ms) {
  const timeMs = Number(ms);
  if (!Number.isFinite(timeMs) || timeMs <= 0) return '';

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(new Date(timeMs));

  const get = type => parts.find(p => p.type === type)?.value || '';
  return `${get('hour')}:${get('minute')}:${get('second')}`;
}

function parseQuoteTimestampMs(value) {
  if (value === undefined || value === null || value === '') return Date.now();

  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > 0) {
    return numeric < 10000000000 ? numeric * 1000 : numeric;
  }

  const parsed = Date.parse(String(value));
  return Number.isFinite(parsed) ? parsed : Date.now();
}

function normalizeQuotePrice(value) {
  const n = cleanNumber(value);
  return n === '' || !Number.isFinite(n) || n <= 0 ? '' : n;
}

function bestQuotePrice(quote) {
  if (!quote) return '';

  const direct = firstCleanNumber(quote.price, quote.market_price, quote.marketPrice, quote.last, quote.close);
  if (direct !== '' && direct > 0) return direct;

  const bid = normalizeQuotePrice(quote.bid);
  const ask = normalizeQuotePrice(quote.ask);
  if (bid !== '' && ask !== '' && bid > 0 && ask > 0) {
    return Number(((bid + ask) / 2).toFixed(4));
  }

  return '';
}

function upsertLiveQuote(rawQuote, payloadTimestamp = '') {
  if (!rawQuote || typeof rawQuote !== 'object') return false;

  const symbol = normalizeSymbol(rawQuote.symbol || rawQuote.ticker);
  if (!symbol) return false;

  const price = bestQuotePrice(rawQuote);
  if (price === '') return false;

  const timestampMs = parseQuoteTimestampMs(rawQuote.timestamp_ms || rawQuote.timestamp || rawQuote.updated_at || payloadTimestamp);

  LIVE_QUOTES.set(symbol, {
    symbol,
    price,
    bid: normalizeQuotePrice(rawQuote.bid),
    ask: normalizeQuotePrice(rawQuote.ask),
    last: normalizeQuotePrice(rawQuote.last),
    close: normalizeQuotePrice(rawQuote.close),
    source: String(rawQuote.source || rawQuote.quote_source || 'TWS').trim() || 'TWS',
    market_data_type: rawQuote.market_data_type ?? rawQuote.marketDataType ?? '',
    timestamp_ms: timestampMs,
    received_ms: Date.now(),
  });

  return true;
}

function liveQuoteForSymbol(symbol) {
  const cleanSymbol = normalizeSymbol(symbol);
  if (!cleanSymbol) return null;

  const quote = LIVE_QUOTES.get(cleanSymbol);
  if (!quote) return null;

  const ageSeconds = (Date.now() - Number(quote.timestamp_ms || quote.received_ms || 0)) / 1000;
  if (!Number.isFinite(ageSeconds) || ageSeconds > LIVE_QUOTE_STALE_SECONDS) {
    return { ...quote, stale: true, age_seconds: Number(ageSeconds.toFixed(1)) };
  }

  return { ...quote, stale: false, age_seconds: Number(ageSeconds.toFixed(1)) };
}

function recalcOpenPositionFromLast(row, lastPrice, quote = null) {
  const last = cleanNumber(lastPrice);
  if (last === '' || last <= 0) return row;

  const entry = cleanNumber(row.entry);
  const size = cleanNumber(row.size);
  const target = cleanNumber(row.target);
  const stop = cleanNumber(row.stop);
  const side = String(row.side || '').toUpperCase();

  const enriched = {
    ...row,
    last: Number(last.toFixed(2)),
    quote_source: quote ? (quote.stale ? `${quote.source || 'TWS'} stale` : quote.source || 'TWS') : row.quote_source || 'Sheets',
    quote_time: quote ? formatNyTimeFromMs(quote.timestamp_ms) : row.quote_time || '',
    quote_age_seconds: quote ? quote.age_seconds : row.quote_age_seconds ?? '',
    quote_stale: quote ? Boolean(quote.stale) : Boolean(row.quote_stale),
  };

  if (entry !== '' && size !== '') {
    if (side === 'LONG') {
      enriched.open_pnl = Number(((last - entry) * size).toFixed(2));
    } else if (side === 'SHORT') {
      enriched.open_pnl = Number(((entry - last) * size).toFixed(2));
    }
  }

  if (target !== '' && last !== 0) {
    if (side === 'LONG') {
      enriched.to_tp = Number((((target - last) / last) * 100).toFixed(2));
    } else if (side === 'SHORT') {
      enriched.to_tp = Number((((last - target) / last) * 100).toFixed(2));
    }
  }

  if (stop !== '' && last !== 0) {
    if (side === 'LONG') {
      enriched.to_stop = Number((((last - stop) / last) * 100).toFixed(2));
    } else if (side === 'SHORT') {
      enriched.to_stop = Number((((stop - last) / last) * 100).toFixed(2));
    }
  }

  return enriched;
}

function enrichOpenPositionsWithLiveQuotes(openPositions) {
  // GoogleFinance-only dashboard mode.
  // Keep accepting /bridge/quotes for backwards compatibility, but do not use
  // the TWS quote cache to override Google Sheets / GoogleFinance values.
  return (openPositions || []).map(row => ({
    ...row,
    quote_source: row.last !== '' ? 'GoogleFinance' : '',
    quote_time: '',
    quote_age_seconds: '',
    quote_stale: false,
  }));
}

function quoteStatusForOpenPositions(openPositions) {
  const rows = openPositions || [];

  return {
    source: rows.length ? 'GoogleFinance' : 'No open positions',
    live_count: 0,
    total_count: rows.length,
    updated_time: '',
    stale_seconds: LIVE_QUOTE_STALE_SECONDS,
  };
}


function marketDataTypeLabel(value) {
  const n = Number(value);
  if (n === 1) return 'LIVE';
  if (n === 2) return 'FROZEN';
  if (n === 3) return 'DELAYED';
  if (n === 4) return 'DELAYED FROZEN';
  return 'UNKNOWN';
}

function ownerQuoteStatusLabel(quote) {
  if (!quote) return 'NO TWS QUOTE';

  const dataType = marketDataTypeLabel(quote.market_data_type);
  return quote.stale ? `${dataType} · STALE` : dataType;
}

function enrichOpenPositionsForOwner(openPositions) {
  return (openPositions || []).map(row => {
    const quote = liveQuoteForSymbol(row.symbol);

    if (!quote) {
      return {
        ...row,
        bid: '',
        ask: '',
        quote_source: row.last !== '' ? 'GoogleFinance fallback' : '',
        quote_time: '',
        quote_age_seconds: '',
        quote_stale: true,
        quote_status: 'NO TWS QUOTE',
        market_data_type: '',
      };
    }

    const enriched = recalcOpenPositionFromLast(row, quote.price, quote);

    return {
      ...enriched,
      bid: quote.bid,
      ask: quote.ask,
      quote_status: ownerQuoteStatusLabel(quote),
      market_data_type: quote.market_data_type,
    };
  });
}

function ownerQuoteStatusForOpenPositions(openPositions) {
  const rows = openPositions || [];
  const withQuote = rows.filter(row => row.quote_status && row.quote_status !== 'NO TWS QUOTE');
  const fresh = withQuote.filter(row => !row.quote_stale);
  const latestMs = withQuote.reduce((latest, row) => {
    const quote = LIVE_QUOTES.get(normalizeSymbol(row.symbol));
    return Math.max(latest, Number(quote?.timestamp_ms || quote?.received_ms || 0));
  }, 0);

  return {
    source: 'IBKR / TWS owner-only',
    live_count: fresh.length,
    total_count: rows.length,
    updated_time: latestMs ? formatNyTimeFromMs(latestMs) : '',
    stale_seconds: LIVE_QUOTE_STALE_SECONDS,
  };
}

function ownerQuoteCachePayload() {
  const quotes = Array.from(LIVE_QUOTES.keys())
    .map(symbol => liveQuoteForSymbol(symbol))
    .filter(Boolean)
    .map(quote => ({
      symbol: quote.symbol,
      price: quote.price,
      bid: quote.bid,
      ask: quote.ask,
      last: quote.last,
      close: quote.close,
      source: quote.source,
      market_data_type: quote.market_data_type,
      market_data_label: marketDataTypeLabel(quote.market_data_type),
      quote_status: ownerQuoteStatusLabel(quote),
      timestamp_ms: quote.timestamp_ms,
      quote_time: formatNyTimeFromMs(quote.timestamp_ms),
      age_seconds: quote.age_seconds,
      stale: quote.stale,
    }));

  return {
    ok: true,
    updated_at: nowNy(),
    stale_seconds: LIVE_QUOTE_STALE_SECONDS,
    count: quotes.length,
    quotes,
  };
}

function normalizeRawMessage(reqBody) {
  return typeof reqBody === 'string'
    ? reqBody
    : JSON.stringify(reqBody, null, 2);
}

function googleFinanceSymbolFormula(rowNum) {
  return `=IF(C${rowNum}="","",IFERROR(GOOGLEFINANCE(REGEXREPLACE(C${rowNum},".*:",""),"price"),""))`;
}

function unrealizedFormula(rowNum) {
  return `=IF(OR(C${rowNum}="",J${rowNum}="",F${rowNum}="",G${rowNum}=""),"",IF(D${rowNum}="LONG",(J${rowNum}-F${rowNum})*G${rowNum},(F${rowNum}-J${rowNum})*G${rowNum}))`;
}

function parseUpdatedRowNumber(updatedRange) {
  const match = String(updatedRange || '').match(/![A-Z]+(\d+):/);
  return match ? Number(match[1]) : null;
}

function formatMoney(value) {
  const n = cleanNumber(value);
  if (n === '') return '';

  const sign = n > 0 ? '+' : n < 0 ? '-' : '';
  const abs = Math.abs(n).toFixed(2);

  return `${sign}$${abs}`;
}

function formatPercent(value) {
  const n = cleanNumber(value);
  if (n === '') return '';

  const sign = n > 0 ? '+' : n < 0 ? '-' : '';
  const abs = Math.abs(n).toFixed(2);

  return `${sign}${abs}%`;
}

function firstCleanNumber(...values) {
  for (const value of values) {
    const n = cleanNumber(value);
    if (n !== '') return n;
  }

  return '';
}

function calcResult(openPosition, closeRow) {
  // Primary path: use the real open position from Google Sheets.
  // Fallback path: if Open Positions did not contain a matching row, calculate from the close payload itself.
  // This protects Telegram / Closed Trades from showing $0.00 when the close alert has entry, exit, side, and qty.
  const entry = firstCleanNumber(openPosition?.entry, closeRow?.entry, closeRow?.entry_price);
  const exit = firstCleanNumber(closeRow?.exit, closeRow?.price, closeRow?.exit_price, closeRow?.filled_price, closeRow?.fill_price);
  const size = firstCleanNumber(openPosition?.size, closeRow?.size, closeRow?.qty, closeRow?.quantity);
  const side = String(openPosition?.side || closeRow?.side || '').toUpperCase();

  if (entry === '' || exit === '' || size === '' || !side) return '';

  if (side === 'LONG') {
    return Number(((exit - entry) * size).toFixed(2));
  }

  if (side === 'SHORT') {
    return Number(((entry - exit) * size).toFixed(2));
  }

  return '';
}

function calcResultPercent(openPosition, closeRow) {
  const entry = firstCleanNumber(openPosition?.entry, closeRow?.entry, closeRow?.entry_price);
  const size = firstCleanNumber(openPosition?.size, closeRow?.size, closeRow?.qty, closeRow?.quantity);
  const result = firstCleanNumber(closeRow?.result, closeRow?.pnl, closeRow?.realized_pnl, closeRow?.p_l);

  if (entry === '' || size === '' || result === '') return '';

  const notional = entry * size;

  if (!Number.isFinite(notional) || notional === 0) return '';

  return Number(((result / notional) * 100).toFixed(2));
}

function ensureClosePnlFallback(row, openPosition = null) {
  if (!row || !['TP', 'SL', 'EOD'].includes(row.event)) return row;

  const enriched = { ...row };

  if (enriched.result === '' || enriched.result === undefined || enriched.result === null) {
    enriched.result = calcResult(openPosition, enriched);
  }

  if (enriched.result_pct === '' || enriched.result_pct === undefined || enriched.result_pct === null) {
    enriched.result_pct = calcResultPercent(openPosition, enriched);
  }

  return enriched;
}

function pnlTelegramLine(row) {
  const result = cleanNumber(row?.result);
  const resultPct = cleanNumber(row?.result_pct);

  if (result === '') return '';

  const emoji = result > 0 ? '😊' : result < 0 ? '😞' : '😐';
  const money = formatMoney(result);
  const pct = resultPct === '' ? '' : ` / ${formatPercent(resultPct)}`;

  return `${emoji} <b>${money}${pct}</b>`;
}

function enrichCloseRowFromOpenPosition(closeRow, openPosition) {
  if (!openPosition) {
    return ensureClosePnlFallback({
      ...closeRow,
      status: 'closed',
    });
  }

  const enriched = {
    ...closeRow,
    trade_id: closeRow.trade_id || openPosition.trade_id || makeTradeId(openPosition.symbol, openPosition.side),
    symbol: closeRow.symbol || openPosition.symbol || '',
    side: closeRow.side || openPosition.side || '',
    entry: closeRow.entry !== '' ? closeRow.entry : openPosition.entry || '',
    size: closeRow.size !== '' ? closeRow.size : openPosition.size || '',
    target: closeRow.target !== '' ? closeRow.target : openPosition.target || '',
    stop: closeRow.stop !== '' ? closeRow.stop : openPosition.stop || '',
    status: 'closed',
  };

  return ensureClosePnlFallback(enriched, openPosition);
}


function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function moneyClass(value) {
  const n = cleanNumber(value);
  if (n === '') return '';
  if (n > 0) return 'positive';
  if (n < 0) return 'negative';
  return 'neutral';
}

function sideClass(side) {
  const s = String(side || '').toUpperCase();
  if (s === 'LONG') return 'long';
  if (s === 'SHORT') return 'short';
  return '';
}

function num(value, decimals = 2) {
  const n = cleanNumber(value);
  if (n === '') return '';
  return n.toFixed(decimals);
}

function pct(value) {
  const n = cleanNumber(value);
  if (n === '') return '';
  return `${n.toFixed(2)}%`;
}

function safeDateText(value) {
  return String(value || '').replace('T', ' ').slice(0, 19);
}

function parseCookies(req) {
  const header = req.headers.cookie || '';

  return header.split(';').reduce((cookies, part) => {
    const [key, ...valueParts] = part.trim().split('=');

    if (!key) return cookies;

    cookies[key] = decodeURIComponent(valueParts.join('=') || '');
    return cookies;
  }, {});
}

function isDashboardAuthorized(req) {
  const keyFromQuery = String(req.query.key || '').trim();
  const cookies = parseCookies(req);
  const keyFromCookie = String(cookies.vixale_dashboard_key || '').trim();
  const dashboardKey = String(DASHBOARD_KEY || '').trim();

  return Boolean(dashboardKey) && (keyFromQuery === dashboardKey || keyFromCookie === dashboardKey);
}


function isAdminAuthorized(req) {
  const keyFromQuery = String(req.query.key || '').trim();
  const cookies = parseCookies(req);
  const keyFromCookie = String(cookies.vixale_admin_key || '').trim();
  const adminKey = String(ADMIN_DASHBOARD_KEY || '').trim();

  return Boolean(adminKey) && (keyFromQuery === adminKey || keyFromCookie === adminKey);
}

function isQuoteBridgeAuthorized(req) {
  const configuredKey = String(QUOTE_BRIDGE_KEY || '').trim();
  if (!configuredKey) return false;

  const headerKey = String(req.headers['x-vixale-quote-key'] || '').trim();
  const queryKey = String(req.query.key || '').trim();

  return headerKey === configuredKey || queryKey === configuredKey;
}

function setPrivateNoStoreHeaders(res) {
  res.set({
    'Cache-Control': 'private, no-store, no-cache, must-revalidate, max-age=0',
    Pragma: 'no-cache',
    Expires: '0',
    'X-Robots-Tag': 'noindex, nofollow, noarchive',
  });
}

//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// OLD TEXT ALERT PARSER — keeps older TV scripts working
//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

function parseTradingViewMessage(message) {
  const raw = String(message || '').trim();

  let symbol = '';
  let side = '';
  let event = '';

  const firstLine = raw.split('\n')[0] || '';

  const headerMatch = raw.match(/([A-Z0-9:_\.\-!]+)\s+(LONG|SHORT)/i);
  if (headerMatch) {
    symbol = headerMatch[1].trim().replace(/^[^A-Z0-9:_\.\-!]+/i, '');
    side = headerMatch[2].trim().toUpperCase();
  }

  if (/CANCELED|CANCELLED/i.test(firstLine) || /CANCELED|CANCELLED/i.test(raw)) {
    event = 'CANCEL';
  } else if (/Entry filled/i.test(raw) || /\bFILLED\b/i.test(firstLine)) {
    event = 'FILL';
  } else if (/EOD CLOSE|RTH END CLOSE/i.test(firstLine) || /RTH End Close/i.test(raw)) {
    event = 'EOD';
  } else if (/TARGET HIT|TAKE PROFIT|\bTP\b/i.test(firstLine) || /ЦЕЛЬ/i.test(firstLine) || /Profit:/i.test(raw)) {
    event = 'TP';
  } else if (/STOP LOSS|\bSTOP\b|\bSL\b|CLOSE STOP/i.test(firstLine) || /СТОП/i.test(firstLine) || /Actual loss:/i.test(raw)) {
    event = 'SL';
  } else if (/SETUP/i.test(firstLine)) {
    event = 'SETUP';
  } else {
    event = 'UNKNOWN';
  }

  const entry =
    cleanNumber(extract(/Entry Limit:\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Entry filled:\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Entry:\s*([0-9\.,-]+)/i, raw));

  const size =
    cleanNumber(extract(/Qty:\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Suggested Size:\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Size:\s*([0-9\.,-]+)/i, raw));

  const target =
    cleanNumber(extract(/ЦЕЛЬ:\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Target:\s*([0-9\.,-]+)/i, raw));

  const filled =
    cleanNumber(extract(/Filled:\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Entry filled:\s*([0-9\.,-]+)/i, raw));

  const close =
    cleanNumber(extract(/Exit Close:\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Close:\s*([0-9\.,-]+)/i, raw));

  const stop =
    cleanNumber(extract(/СТОП на закрытие (?:ниже|выше)\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Stop:\s*close beyond\s*([0-9\.,-]+)/i, raw)) ||
    cleanNumber(extract(/Stop:\s*([0-9\.,-]+)/i, raw));

  let exit = '';
  if (event === 'TP') exit = filled || close || target;
  if (event === 'SL' || event === 'EOD') exit = close || filled;

  let result = '';

  if (event === 'TP') {
    result = cleanNumber(extract(/Profit:\s*([+\-]?\$?[0-9\.,-]+)/i, raw));
  }

  if (event === 'SL') {
    const loss = cleanNumber(extract(/Actual loss:\s*([+\-]?\$?[0-9\.,-]+)/i, raw));
    result = loss === '' ? '' : -Math.abs(loss);
  }

  if (event === 'EOD') {
    result = cleanNumber(extract(/Result:\s*([+\-]?\$?[0-9\.,-]+)/i, raw));
  }

  const status =
    event === 'SETUP' ? 'pending' :
    event === 'FILL' ? 'open' :
    event === 'TP' ? 'closed' :
    event === 'SL' ? 'closed' :
    event === 'EOD' ? 'closed' :
    event === 'CANCEL' ? 'canceled' :
    event === 'RECONCILE_FLAT' ? 'reconciled' :
    'unknown';

  const trade_id = makeTradeId(symbol, side);

  return {
    timestamp: nowNy(),
    trade_id,
    symbol,
    side,
    event,
    entry,
    size,
    target,
    stop,
    exit,
    result,
    result_pct: '',
    status,
    raw,
    raw_event: event,
  };
}

//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// NEW JSON ALERT PARSER — for new FVG live TV script
//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

function parseJsonTradingViewAlert(data) {
  const eventRaw = String(data.event || '').toUpperCase();
  const exitTypeRaw = String(data.exit_type || '').toUpperCase();
  const strategyName = String(data.strategy || data.strategy_name || '').trim();
  const profileName = String(data.profile || data.alert_profile || '').trim();
  const variantName = String(data.variant || '').trim();
  const eodPolicy = String(data.eod_policy || '').trim();
  const isV51Intraday = isV51IntradayName(strategyName) || isV51IntradayName(profileName);
  const isOppositeFlip = isOppositeFlipName(strategyName) || isOppositeFlipName(profileName) || isOppositeFlipName(variantName) || isOppositeFlipName(data.target_type);
  const isEmaPullback = isEmaPullbackName(strategyName) || isEmaPullbackName(profileName) || isEmaPullbackName(variantName);
  const openOnSetup = isV51Intraday || isOppositeFlip || isEmaPullback;

  const eventMap = {
    PENDING_SETUP: 'PENDING_SETUP',
    SETUP: 'SETUP',
    ENTRY: 'SETUP',
    ENTRY_FILL: 'FILL',
    FILL: 'FILL',

    TP: 'TP',
    TARGET: 'TP',

    CLOSE_STOP: 'SL',
    STOP: 'SL',
    SL: 'SL',

    EOD: 'EOD',
    EOD_CLOSE: 'EOD',
    NEW_DAY_EMERGENCY_CLOSE: 'EOD',

    CANCEL: 'CANCEL',
    CANCELED: 'CANCEL',
    CANCELLED: 'CANCEL',
    SETUP_CANCELED: 'CANCEL',
    SETUP_CANCELLED: 'CANCEL',
    ORDER_CANCELED: 'CANCEL',
    ORDER_CANCELLED: 'CANCEL',
    EOD_RESET: 'CANCEL',
    NEW_DAY_RESET: 'CANCEL',
    CANCEL_REPLACE: 'CANCEL',

    RECONCILE_FLAT: 'RECONCILE_FLAT',
    IB_CONFIRMED_FLAT: 'RECONCILE_FLAT',
    FLAT_RECONCILE: 'RECONCILE_FLAT',

    STOP_REF_UPDATE: 'STOP_REF_UPDATE',
    STOP_REFERENCE_UPDATE: 'STOP_REF_UPDATE',
    SUPER_TREND_STOP_REF_UPDATE: 'STOP_REF_UPDATE',
  };

  let event = eventMap[eventRaw] || eventRaw || 'UNKNOWN';

  if (eventRaw === 'EXIT') {
    if (exitTypeRaw === 'TARGET') event = 'TP';
    else if (exitTypeRaw === 'STOP') event = 'SL';
    else if (exitTypeRaw === 'EOD') event = 'EOD';
    else event = 'UNKNOWN';
  }

  const symbol = String(data.symbol || data.ticker || '').trim();

  // If side is missing on EOD_RESET / NEW_DAY_RESET, leave side blank.
  // That lets us remove all pending rows by symbol.
  const side = data.side ? String(data.side).trim().toUpperCase() : '';

  const entry =
    cleanNumber(data.entry) ||
    cleanNumber(data.entry_price) ||
    cleanNumber(data.price);

  const size =
    cleanNumber(data.qty) ||
    cleanNumber(data.size) ||
    cleanNumber(data.quantity) ||
    BRIDGE_DEFAULT_QTY;

  const target = cleanNumber(data.target);
  const stop = cleanNumber(data.stop);
  const price = firstCleanNumber(
    data.price,
    data.exit,
    data.exit_price,
    data.avg_fill_price,
    data.average_fill_price,
    data.filled_price,
    data.fill_price,
    data.last_fill_price
  );

  let exit = '';
  if (event === 'TP' || event === 'SL' || event === 'EOD') {
    exit = price;
  }

  let result = firstCleanNumber(
    data.result,
    data.result_usd,
    data.pnl,
    data.p_l,
    data.realized_pnl,
    data.realized_p_l
  );

  const resultPct = firstCleanNumber(
    data.result_pct,
    data.result_percent,
    data.pnl_pct,
    data.pnl_percent,
    data.percent
  );

  const trade_id = makeTradeId(symbol, side);

  const status =
    event === 'PENDING_SETUP' ? 'pending' :
    event === 'SETUP' ? (openOnSetup ? 'open' : 'pending') :
    event === 'FILL' ? 'open' :
    event === 'TP' || event === 'SL' || event === 'EOD' ? 'closed' :
    event === 'CANCEL' ? 'canceled' :
    event === 'RECONCILE_FLAT' ? 'reconciled' :
    event === 'STOP_REF_UPDATE' ? 'updated' :
    'unknown';

  return {
    timestamp: nowNy(),
    trade_id,
    symbol,
    side,
    event,
    entry,
    size,
    target,
    stop,
    exit,
    result,
    result_pct: resultPct,
    status,
    raw: JSON.stringify(data, null, 2),
    strategy: strategyName,
    profile: profileName,
    variant: variantName,
    eod_policy: eodPolicy,
    sec_type: data.sec_type ?? '',
    asset_class: data.asset_class ?? '',
    exchange: data.exchange ?? '',
    currency: data.currency ?? '',
    stop_type: data.stop_type ?? '',
    target_type: data.target_type ?? '',
    st_atr_period: data.st_atr_period ?? '',
    st_factor: data.st_factor ?? '',
    risk_atr_period: data.risk_atr_period ?? '',
    atr_target_mult: data.atr_target_mult ?? '',

    box_top: data.box_top ?? '',
    box_bottom: data.box_bottom ?? '',
    min_box_atr: data.min_box_atr ?? '',
    depth_pct: data.depth_pct ?? '',
    tp_atr: data.tp_atr ?? '',
    qty_mode: data.qty_mode ?? '',
    risk_pct: data.risk_pct ?? '',
    max_position_pct: data.max_position_pct ?? '',
    raw_event: eventRaw,
    reason: data.reason ?? '',
    payload_version: data.payload_version ?? '',
    system_id: data.system_id ?? '',
    setup_id: String(data.setup_id || '').trim(),
    alert_instance_id: data.alert_instance_id ?? '',
    cancel_scope: data.cancel_scope ?? '',
    timeframe: data.timeframe ?? '',
    flip_bar_time: data.flip_bar_time ?? '',
    planned_limit_entry: data.planned_limit_entry ?? '',
  };
}

//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// PRETTY TELEGRAM FORMATTER
//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

function formatTelegramMessage(row, originalMessage) {
  if (!row || row.event === 'UNKNOWN') return originalMessage;

  const titleBase = `${row.symbol || ''} ${row.side || ''}`.trim();
  const pnlLine = pnlTelegramLine(row);

  if (row.event === 'PENDING_SETUP' && isVixaleEdgePendingLifecycleRow(row)) {
    return [
      `🟣 <b>Vixale Edge setup ${row.side}</b>`,
      '',
      `<b>${row.symbol}${row.timeframe ? ` · ${row.timeframe}` : ''}</b>`,
      row.entry !== '' ? `Planned Entry: <b>${row.entry}</b>` : '',
      row.target !== '' ? `Target: <b>${row.target}</b>` : '',
      row.stop !== '' ? `Stop Loss Ref: <b>${row.stop}</b>` : '',
    ].filter(Boolean).join('\n');
  }

  if (row.event === 'SETUP') {
    const emoji = row.side === 'SHORT' ? '🔴' : '🟢';

    if (isFionaLimitPullbackRow(row)) {
      return [
        `🟣 <b>Vixale Edge opened ${row.side}</b>`,
        '',
        `<b>${row.symbol}</b>`,
        row.entry !== '' ? `📍 Entry: <b>${row.entry}</b>` : '',
        row.target !== '' ? `🎯 Target: <b>${row.target}</b>` : '',
        row.stop !== '' ? `🛑 Stop Ref: <b>${row.stop}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      ].filter(Boolean).join('\n');
    }

    if (isOppositeFlipRow(row)) {
      return [
        `${emoji} <b>Vixale Prime opened ${row.side}</b>`,
        '',
        `<b>${row.symbol}</b>`,
        row.entry !== '' ? `📍 Entry: <b>${row.entry}</b>` : '',
        row.target !== '' ? `🎯 Target: <b>${row.target}</b>` : '',
        row.stop !== '' ? `🛑 Stop Ref: <b>${row.stop}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      ].filter(Boolean).join('\n');
    }

    if (isEmaPullbackRow(row)) {
      return [
        `🕺 <b>Elvis in the Building!</b>`,
        '',
        `<b>${titleBase}</b>`,
        row.entry !== '' ? `📍 Entry: <b>${row.entry}</b>` : '',
        row.target !== '' ? `🎯 Target: <b>${row.target}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      ].filter(Boolean).join('\n');
    }

    if (isV51IntradayRow(row)) {
      return [
        `${emoji} <b>${titleBase} OPENED</b>`,
        '',
        row.entry !== '' ? `📍 Entry: <b>${row.entry}</b>` : '',
        row.target !== '' ? `🎯 ATR Target: <b>${row.target}</b>` : '',
        row.stop !== '' ? `🛑 Stop Ref: <b>${row.stop}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      ].filter(Boolean).join('\n');
    }

    return [
      `${emoji} <b>${titleBase} SETUP</b>`,
      '',
      row.entry !== '' ? `📍 Entry Limit: <b>${row.entry}</b>` : '',
      row.target !== '' ? `🎯 Target: <b>${row.target}</b>` : '',
      row.stop !== '' ? `⛔ Stop: close beyond <b>${row.stop}</b>` : '',
      row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
    ].filter(Boolean).join('\n');
  }

  if (row.event === 'FILL') {
    if (isFionaLimitPullbackRow(row)) {
      return [
        `🟣 <b>Vixale Edge opened ${row.side}</b>`,
        '',
        `<b>${row.symbol}</b>`,
        row.entry !== '' ? `📍 Entry: <b>${row.entry}</b>` : '',
        row.target !== '' ? `🎯 Target: <b>${row.target}</b>` : '',
        row.stop !== '' ? `🛑 Stop Ref: <b>${row.stop}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      ].filter(Boolean).join('\n');
    }

    if (isOppositeFlipRow(row)) {
      const emoji = row.side === 'SHORT' ? '🔴' : '🟢';
      return [
        `${emoji} <b>Vixale Prime opened ${row.side}</b>`,
        '',
        `<b>${row.symbol}</b>`,
        row.entry !== '' ? `📍 Entry: <b>${row.entry}</b>` : '',
        row.target !== '' ? `🎯 Target: <b>${row.target}</b>` : '',
        row.stop !== '' ? `🛑 Stop Ref: <b>${row.stop}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      ].filter(Boolean).join('\n');
    }

    if (isEmaPullbackRow(row)) {
      return [
        `🕺 <b>Elvis in the Building!</b>`,
        '',
        `<b>${titleBase}</b>`,
        row.entry !== '' ? `📍 Entry: <b>${row.entry}</b>` : '',
        row.target !== '' ? `🎯 Target: <b>${row.target}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      ].filter(Boolean).join('\n');
    }

    return [
      `🎉 <b>${titleBase} FILLED</b>`,
      '',
      row.entry !== '' ? `✅ Entry: <b>${row.entry}</b>` : '',
      row.target !== '' ? `🎯 Target: <b>${row.target}</b>` : '',
      row.stop !== '' ? `⛔ Stop: close beyond <b>${row.stop}</b>` : '',
      row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
    ].filter(Boolean).join('\n');
  }

  if (row.event === 'TP') {
    if (isFionaLimitPullbackRow(row)) {
      return [
        `🎯 <b>Vixale Edge hit target</b>`,
        '',
        `<b>${titleBase}</b>`,
        row.exit !== '' ? `Exit: <b>${row.exit}</b>` : '',
        row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
        pnlLine,
      ].filter(Boolean).join('\n');
    }

    if (isOppositeFlipRow(row)) {
      return [
        `🎯 <b>Vixale Prime hit target</b>`,
        '',
        `<b>${titleBase}</b>`,
        row.exit !== '' ? `Exit: <b>${row.exit}</b>` : '',
        row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
        pnlLine,
      ].filter(Boolean).join('\n');
    }

    if (isEmaPullbackRow(row)) {
      return [
        `🎯 <b>Elvis hit target</b>`,
        '',
        `<b>${titleBase}</b>`,
        row.exit !== '' ? `Exit: <b>${row.exit}</b>` : '',
        row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
        pnlLine,
      ].filter(Boolean).join('\n');
    }

    return [
      `🎯 <b>${titleBase} TAKE PROFIT HIT</b>`,
      '',
      row.exit !== '' ? `✅ Exit Price: <b>${row.exit}</b>` : '',
      row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
      row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      pnlLine,
    ].filter(Boolean).join('\n');
  }

  if (row.event === 'SL') {
    if (isFionaLimitPullbackRow(row)) {
      return [
        `🛑 <b>Vixale Edge hit Stop Loss</b>`,
        '',
        `<b>${row.symbol}</b>`,
        row.exit !== '' ? `Exit: <b>${row.exit}</b>` : '',
        row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
        pnlLine,
      ].filter(Boolean).join('\n');
    }

    if (isOppositeFlipRow(row)) {
      return [
        `🛑 <b>Vixale Prime hit Stop Loss</b>`,
        '',
        `<b>${row.symbol}</b>`,
        row.exit !== '' ? `Exit: <b>${row.exit}</b>` : '',
        row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
        pnlLine,
      ].filter(Boolean).join('\n');
    }

    if (isEmaPullbackRow(row)) {
      return [
        `🎸 <b>Elvis has left the building</b>`,
        '',
        `<b>${titleBase} position closed</b>`,
        row.exit !== '' ? `Exit: <b>${row.exit}</b>` : '',
        row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
        row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
        pnlLine,
      ].filter(Boolean).join('\n');
    }

    return [
      `🛑 <b>${titleBase} MARKET STOP</b>`,
      '',
      row.exit !== '' ? `❌ Exit Price: <b>${row.exit}</b>` : '',
      row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
      row.size !== '' ? `📦 Qty: <b>${row.size}</b>` : '',
      pnlLine,
    ].filter(Boolean).join('\n');
  }

  if (row.event === 'EOD') {
    if (isFionaLimitPullbackRow(row)) {
      return [
        `⏰ <b>Vixale Edge EOD close</b>`,
        '',
        `<b>${titleBase || row.symbol}</b>`,
        row.exit !== '' ? `Exit Price: <b>${row.exit}</b>` : '',
        row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
        row.size !== '' ? `Qty: <b>${row.size}</b>` : '',
        pnlLine,
      ].filter(Boolean).join('\n');
    }

    if (isOppositeFlipRow(row)) {
      return [
        `⏰ <b>Vixale Prime EOD close</b>`,
        '',
        `<b>${titleBase || row.symbol}</b>`,
        row.exit !== '' ? `Exit Price: <b>${row.exit}</b>` : '',
        row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
        row.size !== '' ? `Qty: <b>${row.size}</b>` : '',
        pnlLine,
      ].filter(Boolean).join('\n');
    }

    return [
      `⏰ <b>${titleBase || row.symbol} EOD CLOSE</b>`,
      '',
      row.exit !== '' ? `Exit Price: <b>${row.exit}</b>` : '',
      row.entry !== '' ? `Entry: <b>${row.entry}</b>` : '',
      row.size !== '' ? `Qty: <b>${row.size}</b>` : '',
      pnlLine,
    ].filter(Boolean).join('\n');
  }

  if (row.event === 'CANCEL') {
    if (
      isVixaleEdgePendingCancel(row) &&
      String(row.reason || '').toUpperCase() === 'UNFILLED_BY_MARKET_CLOSE'
    ) {
      return [
        '⚪ <b>Vixale Edge setup canceled</b>',
        '',
        `<b>${row.symbol} ${row.side}${row.timeframe ? ` · ${row.timeframe}` : ''}</b>`,
        'Reason: Unfilled by market close',
      ].filter(Boolean).join('\n');
    }

    const resetText = row.raw_event === 'EOD_RESET'
      ? 'EOD pending orders canceled'
      : row.raw_event === 'NEW_DAY_RESET'
        ? 'New day reset: old pending orders canceled'
        : 'Setup canceled / replaced';

    return [
      `⚪ <b>${titleBase || row.symbol} ${resetText}</b>`,
      '',
      row.reason ? `Reason: ${row.reason}` : '',
    ].filter(Boolean).join('\n');
  }

  return originalMessage;
}

//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// GOOGLE SHEETS
//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

async function getSheetsClient() {
  if (!GOOGLE_SHEET_ID || !GOOGLE_SERVICE_ACCOUNT_JSON) {
    console.log('Google Sheets env vars missing. Skipping sheet logging.');
    return null;
  }

  const credentials = JSON.parse(GOOGLE_SERVICE_ACCOUNT_JSON);

  const auth = new google.auth.GoogleAuth({
    credentials,
    scopes: ['https://www.googleapis.com/auth/spreadsheets'],
  });

  return google.sheets({ version: 'v4', auth });
}

async function getSheetIdByName(sheets, sheetName) {
  const response = await sheets.spreadsheets.get({
    spreadsheetId: GOOGLE_SHEET_ID,
  });

  const sheet = response.data.sheets.find(s => s.properties.title === sheetName);
  return sheet ? sheet.properties.sheetId : null;
}

async function readSheet(sheets, sheetName, range = 'A:Z') {
  const response = await sheets.spreadsheets.values.get({
    spreadsheetId: GOOGLE_SHEET_ID,
    range: `${sheetName}!${range}`,
  });

  return response.data.values || [];
}

function findRowIndexByTradeId(values, tradeId) {
  const wanted = normalizeTradeId(tradeId);
  if (!wanted) return -1;

  for (let i = 1; i < values.length; i++) {
    const current = normalizeTradeId(values[i][0] || '');

    if (current === wanted) {
      return i + 1;
    }
  }

  return -1;
}

async function deleteSheetRow(sheets, sheetName, rowNumber) {
  if (!rowNumber || rowNumber < 2) return;

  const sheetId = await getSheetIdByName(sheets, sheetName);
  if (sheetId === null) {
    console.log(`Sheet not found: ${sheetName}`);
    return;
  }

  await sheets.spreadsheets.batchUpdate({
    spreadsheetId: GOOGLE_SHEET_ID,
    requestBody: {
      requests: [
        {
          deleteDimension: {
            range: {
              sheetId,
              dimension: 'ROWS',
              startIndex: rowNumber - 1,
              endIndex: rowNumber,
            },
          },
        },
      ],
    },
  });

  console.log(`Deleted row ${rowNumber} from ${sheetName}`);
}

async function removeRowByTradeId(sheets, sheetName, tradeId) {
  const values = await readSheet(sheets, sheetName);
  const rowNumber = findRowIndexByTradeId(values, tradeId);

  if (rowNumber < 0) return null;

  const existing = values[rowNumber - 1];
  await deleteSheetRow(sheets, sheetName, rowNumber);

  return existing;
}

async function removePendingRowsBySymbol(sheets, symbol) {
  const wantedSymbol = normalizeSymbol(symbol);
  if (!wantedSymbol) return 0;

  const values = await readSheet(sheets, PENDING_SHEET, 'A:J');
  let removedCount = 0;

  for (let i = values.length - 1; i >= 1; i--) {
    const row = values[i];
    const rowSymbol = normalizeSymbol(row[2] || '');

    if (rowSymbol === wantedSymbol) {
      await deleteSheetRow(sheets, PENDING_SHEET, i + 1);
      removedCount++;
    }
  }

  console.log(`Pending rows removed by symbol ${wantedSymbol}: ${removedCount}`);
  return removedCount;
}

async function removePendingRowsBySymbolAndSide(sheets, symbol, side) {
  const wantedSymbol = normalizeSymbol(symbol);
  const wantedSide = String(side || '').trim().toUpperCase();

  if (!wantedSymbol || !wantedSide) return 0;

  const values = await readSheet(sheets, PENDING_SHEET, 'A:J');
  let removedCount = 0;

  for (let i = values.length - 1; i >= 1; i--) {
    const row = values[i];
    const rowSymbol = normalizeSymbol(row[2] || '');
    const rowSide = String(row[3] || '').trim().toUpperCase();

    if (rowSymbol === wantedSymbol && rowSide === wantedSide) {
      await deleteSheetRow(sheets, PENDING_SHEET, i + 1);
      removedCount++;
    }
  }

  console.log(`Pending rows removed by symbol/side ${wantedSymbol}/${wantedSide}: ${removedCount}`);
  return removedCount;
}

async function appendToTradesSheet(sheets, row) {
  if (!['FILL', 'TP', 'SL', 'EOD'].includes(row.event)) {
    console.log('Trades append skipped for non-executed event:', row.event);
    return;
  }

  const eventForSheet = sheetEventLabel(row);

  await sheets.spreadsheets.values.append({
    spreadsheetId: GOOGLE_SHEET_ID,
    range: `${TRADES_SHEET}!A:K`,
    valueInputOption: 'USER_ENTERED',
    requestBody: {
      values: [[
        row.timestamp,
        row.symbol,
        row.side,
        eventForSheet,
        row.entry,
        row.size,
        row.target || row.exit,
        row.stop,
        row.result,
        row.status,
        row.raw,
      ]],
    },
  });

  console.log('Trades row appended:', row.symbol, row.side, eventForSheet);
}

async function upsertPending(sheets, row) {
  if (!row.trade_id) return { created: false };

  const values = await readSheet(sheets, PENDING_SHEET, 'A:J');
  const sheetRow = findRowIndexByTradeId(values, row.trade_id);
  const existing = sheetRow > 0 ? values[sheetRow - 1] : [];

  const pendingRow = [
    row.trade_id,
    row.timestamp || existing[1] || '',
    row.symbol || existing[2] || '',
    row.side || existing[3] || '',
    'pending',
    row.entry || existing[5] || '',
    row.size || existing[6] || '',
    row.target || existing[7] || '',
    row.stop || existing[8] || '',
    row.raw || existing[9] || '',
  ];

  if (sheetRow > 0) {
    await sheets.spreadsheets.values.update({
      spreadsheetId: GOOGLE_SHEET_ID,
      range: `${PENDING_SHEET}!A${sheetRow}:J${sheetRow}`,
      valueInputOption: 'USER_ENTERED',
      requestBody: { values: [pendingRow] },
    });

    console.log('Pending updated:', row.trade_id);
  } else {
    await sheets.spreadsheets.values.append({
      spreadsheetId: GOOGLE_SHEET_ID,
      range: `${PENDING_SHEET}!A:J`,
      valueInputOption: 'USER_ENTERED',
      requestBody: { values: [pendingRow] },
    });

    console.log('Pending appended:', row.trade_id);
  }

  return { created: sheetRow < 0 };
}

async function upsertOpenPosition(sheets, row, pendingRow = null) {
  if (!row.trade_id) return;

  const values = await readSheet(sheets, OPEN_POSITIONS_SHEET, 'A:L');
  const sheetRow = findRowIndexByTradeId(values, row.trade_id);
  const existing = sheetRow > 0 ? values[sheetRow - 1] : [];

  const openTime = row.timestamp || existing[1] || pendingRow?.[1] || '';
  const symbol = row.symbol || existing[2] || pendingRow?.[2] || '';
  const side = row.side || existing[3] || pendingRow?.[3] || '';
  const entry = row.entry || existing[5] || pendingRow?.[5] || '';
  const size = row.size || existing[6] || pendingRow?.[6] || '';
  const target = row.target || existing[7] || pendingRow?.[7] || '';
  const stop = row.stop || existing[8] || pendingRow?.[8] || '';
  const raw = row.raw || existing[11] || pendingRow?.[9] || '';

  let targetRowNumber = sheetRow;

  const openRowWithoutFormulas = [
    row.trade_id,
    openTime,
    symbol,
    side,
    'open',
    entry,
    size,
    target,
    stop,
    '',
    '',
    raw,
  ];

  if (sheetRow > 0) {
    await sheets.spreadsheets.values.update({
      spreadsheetId: GOOGLE_SHEET_ID,
      range: `${OPEN_POSITIONS_SHEET}!A${sheetRow}:L${sheetRow}`,
      valueInputOption: 'USER_ENTERED',
      requestBody: { values: [openRowWithoutFormulas] },
    });

    targetRowNumber = sheetRow;
    console.log('Open position updated:', row.trade_id);
  } else {
    const appendResponse = await sheets.spreadsheets.values.append({
      spreadsheetId: GOOGLE_SHEET_ID,
      range: `${OPEN_POSITIONS_SHEET}!A:L`,
      valueInputOption: 'USER_ENTERED',
      requestBody: { values: [openRowWithoutFormulas] },
    });

    targetRowNumber = parseUpdatedRowNumber(appendResponse.data.updates.updatedRange);
    console.log('Open position appended:', row.trade_id, 'row', targetRowNumber);
  }

  if (targetRowNumber) {
    await sheets.spreadsheets.values.update({
      spreadsheetId: GOOGLE_SHEET_ID,
      range: `${OPEN_POSITIONS_SHEET}!J${targetRowNumber}:K${targetRowNumber}`,
      valueInputOption: 'USER_ENTERED',
      requestBody: {
        values: [[
          googleFinanceSymbolFormula(targetRowNumber),
          unrealizedFormula(targetRowNumber),
        ]],
      },
    });
  }
}

async function updateOpenPositionStopReference(sheets, row) {
  if (!row?.trade_id) {
    return { updated: false, reason: 'missing_trade_id' };
  }

  const stop = cleanNumber(row.stop);
  if (stop === '' || stop <= 0) {
    return { updated: false, reason: `invalid_stop_reference:${row.stop}` };
  }

  const values = await readSheet(sheets, OPEN_POSITIONS_SHEET, 'A:L');
  const sheetRow = findRowIndexByTradeId(values, row.trade_id);

  if (sheetRow < 0) {
    console.log('Stop reference update ignored; no matching open position:', row.trade_id, stop);
    return { updated: false, reason: 'no_matching_open_position' };
  }

  const existing = values[sheetRow - 1] || [];
  const existingRaw = parseRawJsonSafe(existing[11] || '');
  const updateRaw = parseRawJsonSafe(row.raw || '');

  const mergedRawObject = {
    ...updateRaw,
    ...existingRaw,
    event: 'STOP_REF_UPDATE',
    stop,
    stop_ref_updated_at: row.timestamp || nowNy(),
    stop_ref_bar_time: updateRaw.bar_time ?? '',
  };

  const mergedRaw = JSON.stringify(mergedRawObject, null, 2);

  await sheets.spreadsheets.values.batchUpdate({
    spreadsheetId: GOOGLE_SHEET_ID,
    requestBody: {
      valueInputOption: 'USER_ENTERED',
      data: [
        {
          range: `${OPEN_POSITIONS_SHEET}!I${sheetRow}`,
          values: [[stop]],
        },
        {
          range: `${OPEN_POSITIONS_SHEET}!L${sheetRow}`,
          values: [[mergedRaw]],
        },
      ],
    },
  });

  console.log('Open position stop reference updated:', row.trade_id, stop);
  return { updated: true, sheet_row: sheetRow, stop };
}

async function removeOpenPosition(sheets, tradeId) {
  const removed = await removeRowByTradeId(sheets, OPEN_POSITIONS_SHEET, tradeId);
  if (!removed) return null;

  return {
    trade_id: removed[0] || '',
    open_time: removed[1] || '',
    symbol: removed[2] || '',
    side: removed[3] || '',
    status: removed[4] || '',
    entry: removed[5] || '',
    size: removed[6] || '',
    target: removed[7] || '',
    stop: removed[8] || '',
    last_price: removed[9] || '',
    unrealized_p_l: removed[10] || '',
    raw_open: removed[11] || '',
  };
}

async function removeOpenRowsBySymbolAndSide(sheets, symbol, side) {
  const wantedSymbol = normalizeSymbol(symbol);
  const wantedSide = String(side || '').trim().toUpperCase();
  if (!wantedSymbol) return 0;

  const values = await readSheet(sheets, OPEN_POSITIONS_SHEET, 'A:L');
  let removedCount = 0;

  for (let i = values.length - 1; i >= 1; i--) {
    const row = values[i];
    const rowSymbol = normalizeSymbol(row[2] || '');
    const rowSide = String(row[3] || '').trim().toUpperCase();

    if (rowSymbol === wantedSymbol && (!wantedSide || rowSide === wantedSide)) {
      await deleteSheetRow(sheets, OPEN_POSITIONS_SHEET, i + 1);
      removedCount++;
    }
  }

  console.log(`Open rows removed by symbol ${wantedSymbol}${wantedSide ? ` ${wantedSide}` : ''}: ${removedCount}`);
  return removedCount;
}

async function removeOpenRowsBySymbol(sheets, symbol) {
  return removeOpenRowsBySymbolAndSide(sheets, symbol, '');
}

async function appendClosedTrade(sheets, openPosition, closeRow) {
  const eventForSheet = sheetEventLabel(closeRow);

  const closedRow = [
    closeRow.trade_id,
    openPosition?.open_time || '',
    closeRow.timestamp,
    closeRow.symbol || openPosition?.symbol || '',
    closeRow.side || openPosition?.side || '',
    closeRow.entry || openPosition?.entry || '',
    closeRow.exit || '',
    closeRow.size || openPosition?.size || '',
    closeRow.result,
    eventForSheet,
    openPosition?.raw_open || '',
    closeRow.raw,
  ];

  await sheets.spreadsheets.values.append({
    spreadsheetId: GOOGLE_SHEET_ID,
    range: `${CLOSED_TRADES_SHEET}!A:L`,
    valueInputOption: 'USER_ENTERED',
    requestBody: { values: [closedRow] },
  });

  console.log('Closed trade appended:', closeRow.trade_id, eventForSheet, closeRow.result);
}

async function cleanupLegacyPositionIfExists(sheets, tradeId) {
  try {
    await removeRowByTradeId(sheets, LEGACY_POSITIONS_SHEET, tradeId);
  } catch (err) {
    console.log('Legacy Positions cleanup skipped:', err.message);
  }
}

async function processLedger(row) {
  const sheets = await getSheetsClient();

  if (!sheets) return row;

  if (!row || row.event === 'UNKNOWN') return row;

  if (row.event === 'STOP_REF_UPDATE') {
    const updateResult = await updateOpenPositionStopReference(sheets, row);
    return {
      ...row,
      status: updateResult.updated ? 'stop_ref_updated' : 'stop_ref_ignored',
      skip_telegram: true,
      stop_ref_update_result: updateResult,
    };
  }

  if (row.event === 'PENDING_SETUP') {
    if (!isVixaleEdgePendingLifecycleRow(row) || !row.setup_id) return row;

    const pendingRow = {
      ...row,
      trade_id: row.setup_id,
      entry: row.planned_limit_entry || row.entry,
      status: 'pending',
    };
    const result = await upsertPending(sheets, pendingRow);
    return { ...pendingRow, skip_telegram: !result.created };
  }

  if (row.event === 'SETUP') {
    if (!row.trade_id) return row;

    // Execution-first raw SETUP events are intercepted before this function.
    // This branch remains as a guarded fallback for already-confirmed/open callbacks.
    if (isOpenOnSetupRow(row)) {
      const openRow = { ...row, status: 'open' };
      await cleanupLegacyPositionIfExists(sheets, row.trade_id);
      await upsertOpenPosition(sheets, openRow, null);

      const tradesRow = { ...openRow, event: 'FILL', raw_event: row.raw_event || 'SETUP' };
      await appendToTradesSheet(sheets, tradesRow);

      console.log('SETUP treated as open position:', row.trade_id, row.strategy || row.profile || '');
      return openRow;
    }

    await upsertPending(sheets, row);
    return row;
  }

  if (row.event === 'FILL') {
    if (!row.trade_id) return row;

    const pendingRow = await removeRowByTradeId(
      sheets,
      PENDING_SHEET,
      row.setup_id || row.trade_id
    );
    await cleanupLegacyPositionIfExists(sheets, row.trade_id);
    await upsertOpenPosition(sheets, row, pendingRow);
    await appendToTradesSheet(sheets, row);
    return row;
  }

  if (row.event === 'CANCEL') {
    let removedPending = null;
    let removedCount = 0;

    if (isVixaleEdgePendingCancel(row)) {
      removedPending = await removeRowByTradeId(sheets, PENDING_SHEET, row.setup_id);
      removedCount = removedPending ? 1 : 0;
      console.log('Vixale Edge exact pending cleanup:', row.setup_id, 'removed:', removedCount);
      return {
        ...row,
        trade_id: row.setup_id,
        skip_telegram:
          !removedPending ||
          String(row.reason || '').toUpperCase() !== 'UNFILLED_BY_MARKET_CLOSE',
      };
    }

    // First try exact / normalized trade_id match.
    // Example: NASDAQ:NFLX_SHORT and NFLX_SHORT are treated as the same row.
    if (row.trade_id) {
      removedPending = await removeRowByTradeId(sheets, PENDING_SHEET, row.trade_id);
      removedCount = removedPending ? 1 : 0;
      await cleanupLegacyPositionIfExists(sheets, row.trade_id);
    }

    // If trade_id did not match, fall back to symbol + side.
    // This protects the dashboard when TradingView / bridge changes trade_id formatting.
    if (!removedCount && row.symbol && row.side) {
      removedCount = await removePendingRowsBySymbolAndSide(sheets, row.symbol, row.side);
    }

    // Reset events may arrive without side. In that case, remove all pending rows for the symbol.
    if (!removedCount && row.symbol) {
      removedCount = await removePendingRowsBySymbol(sheets, row.symbol);
    }

    // For open-on-SETUP strategies, a bridge/TWS rejection can come back as CANCEL
    // after the app has already placed the SETUP in Open Positions. Clean it up too.
    if (isOpenOnSetupRow(row)) {
      const removedOpen = row.symbol && row.side
        ? await removeOpenRowsBySymbolAndSide(sheets, row.symbol, row.side)
        : row.symbol
          ? await removeOpenRowsBySymbol(sheets, row.symbol)
          : 0;
      console.log('open-on-setup cancel open cleanup removed:', removedOpen);
    }

    console.log('Cancel cleanup finished:', row.trade_id || '', row.symbol || '', row.side || '', 'removed:', removedCount);
    return row;
  }

  if (row.event === 'RECONCILE_FLAT') {
    let removedPending = 0;
    let removedOpen = 0;

    if (row.symbol && row.side) {
      removedPending = await removePendingRowsBySymbolAndSide(sheets, row.symbol, row.side);
      removedOpen = await removeOpenRowsBySymbolAndSide(sheets, row.symbol, row.side);
    } else if (row.symbol) {
      removedPending = await removePendingRowsBySymbol(sheets, row.symbol);
      removedOpen = await removeOpenRowsBySymbol(sheets, row.symbol);
    }

    try {
      if (row.trade_id) await cleanupLegacyPositionIfExists(sheets, row.trade_id);
    } catch (err) {
      console.log('Reconcile legacy cleanup skipped:', err.message);
    }

    console.log('Flat reconcile finished:', row.symbol || '', row.side || '', 'pending removed:', removedPending, 'open removed:', removedOpen);
    return row;
  }

  if (row.event === 'TP' || row.event === 'SL' || row.event === 'EOD') {
    if (!row.trade_id) return row;

    const openPosition = await removeOpenPosition(sheets, row.trade_id);
    await cleanupLegacyPositionIfExists(sheets, row.trade_id);

    if (!openPosition && isOpenOnSetupRow(row)) {
      console.log(
        'Execution-first close had no matching Open Positions row. Skipping duplicate/fake close:',
        row.trade_id,
        row.event,
        row.raw_event || ''
      );
      return {
        ...row,
        status: 'ignored_no_matching_open',
        skip_telegram: true,
      };
    }

    const enrichedCloseRow = enrichCloseRowFromOpenPosition(row, openPosition);

    await appendToTradesSheet(sheets, enrichedCloseRow);
    await appendClosedTrade(sheets, openPosition, enrichedCloseRow);

    return enrichedCloseRow;
  }

  return row;
}

//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// TELEGRAM
//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

async function sendTelegram(message, chatId = CHAT_ID) {
  const targetChatId = String(chatId || '').trim();

  if (!TOKEN || !targetChatId) {
    console.log('Telegram env vars missing or target chat is empty. Skipping Telegram.');
    return { ok: true, skipped: true };
  }

  const url = `https://api.telegram.org/bot${TOKEN}/sendMessage`;

  const payload = {
    chat_id: targetChatId,
    text: message,
    parse_mode: 'HTML',
    disable_web_page_preview: true,
  };

  let response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  let data = await response.json();
  console.log('Telegram response:', JSON.stringify(data));

  if (!data.ok && data.description && String(data.description).includes("can't parse entities")) {
    console.log('Telegram HTML parse failed. Retrying without parse_mode.');

    const fallbackPayload = {
      chat_id: targetChatId,
      text: message,
      disable_web_page_preview: true,
    };

    response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(fallbackPayload),
    });

    data = await response.json();
    console.log('Telegram fallback response:', JSON.stringify(data));
  }

  return data;
}

async function sendAdminTelegram(message) {
  if (!ADMIN_CHAT_ID) {
    console.log('ADMIN_CHAT_ID is not configured. Skipping private admin Telegram notification.');
    return;
  }

  await sendTelegram(message, ADMIN_CHAT_ID);
}


