//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// DASHBOARD DATA
//━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

function parseOpenPositionRow(row) {
  const entry = cleanNumber(row[5]);
  const size = cleanNumber(row[6]);
  const target = cleanNumber(row[7]);
  const stop = cleanNumber(row[8]);
  const last = cleanNumber(row[9]);
  const openPnl = cleanNumber(row[10]);
  const side = String(row[3] || '').toUpperCase();

  let toTp = '';
  let toStop = '';
  let exposure = '';

  if (entry !== '' && size !== '') {
    exposure = Number((entry * size).toFixed(2));
  }

  if (last !== '' && last !== 0 && target !== '') {
    if (side === 'LONG') {
      toTp = Number((((target - last) / last) * 100).toFixed(2));
    } else if (side === 'SHORT') {
      toTp = Number((((last - target) / last) * 100).toFixed(2));
    }
  }

  if (last !== '' && last !== 0 && stop !== '') {
    if (side === 'LONG') {
      toStop = Number((((last - stop) / last) * 100).toFixed(2));
    } else if (side === 'SHORT') {
      toStop = Number((((stop - last) / last) * 100).toFixed(2));
    }
  }

  const rawOpen = row[11] || '';

  return {
    trade_id: row[0] || '',
    open_time: row[1] || '',
    system: strategyFamilyLabelForPosition(rawOpen, stop),
    symbol: row[2] || '',
    side,
    status: row[4] || '',
    entry,
    size,
    target,
    stop,
    last,
    open_pnl: openPnl,
    to_tp: toTp,
    to_stop: toStop,
    exposure,
    raw_open: rawOpen,
    quote_source: last !== '' ? 'GoogleFinance fallback' : '',
    quote_time: '',
    quote_age_seconds: '',
    quote_stale: false,
  };
}

function parsePendingRow(row) {
  const raw = row[9] || '';
  const side = String(row[3] || '').toUpperCase();
  const entry = cleanNumber(row[5]);
  const size = cleanNumber(row[6]);

  return {
    trade_id: row[0] || '',
    timestamp: row[1] || '',
    system: strategyFamilyLabelForPosition(raw, cleanNumber(row[8])),
    symbol: row[2] || '',
    side,
    status: row[4] || '',
    entry,
    size,
    target: cleanNumber(row[7]),
    stop: cleanNumber(row[8]),
    order_type: 'ENTRY SETUP',
    action: side === 'LONG' ? 'BUY' : side === 'SHORT' ? 'SELL SHORT' : 'ENTRY',
    price: entry,
    qty: size,
    raw,
  };
}


function parseRawJsonSafe(value) {
  const raw = String(value || '').trim();
  if (!raw) return {};

  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch (err) {
    return {};
  }
}

function strategyFamilyLabelFromRaw(...rawValues) {
  const joined = rawValues.map(v => String(v || '')).join('\n');

  // Fiona Limit shares the broad Opposite Flip routing identifier with Shrek,
  // so its dedicated variant/profile markers must be checked first.
  const publicLabel = publicSystemLabelFromRaw(joined);
  if (publicLabel) return publicLabel;
  if (isEmaPullbackName(joined)) return 'Elvis';
  if (isV51IntradayName(joined)) return 'Vixale';

  for (const raw of rawValues) {
    const parsed = parseRawJsonSafe(raw);
    const fields = [
      parsed.strategy,
      parsed.strategy_name,
      parsed.profile,
      parsed.alert_profile,
      parsed.variant,
      parsed.target_type,
      parsed.reason,
    ].join(' ');

    const parsedPublicLabel = publicSystemLabelFromRaw(fields);
    if (parsedPublicLabel) return parsedPublicLabel;
    if (isEmaPullbackName(fields)) return 'Elvis';
    if (isV51IntradayName(fields)) return 'Vixale';
  }

  return '';
}

function strategyFamilyLabelForPosition(rawValue, stopValue) {
  const explicitLabel = strategyFamilyLabelFromRaw(rawValue);
  if (explicitLabel) return explicitLabel;

  // Execution-first rows created by older callbacks may have lost strategy
  // metadata in the stored raw payload. Legacy Shrek rows used stop=0, while
  // Elvis rows used a positive EMA-slow reference. New Shrek stop-reference
  // updates also merge strategy metadata into the raw column, so explicit raw
  // identification takes priority before this legacy-only fallback.
  const stop = cleanNumber(stopValue);

  if (stop !== '' && stop > 0) return 'Elvis';
  if (stop === 0) return 'Vixale Prime';

  return '';
}

function exitActionForOpenPosition(side) {
  const cleanSide = String(side || '').toUpperCase();
  if (cleanSide === 'LONG') return 'SELL';
  if (cleanSide === 'SHORT') return 'BUY TO COVER';
  return 'EXIT';
}

function buildWorkingExitOrders(openPositions) {
  return openPositions
    .filter(row => row && row.target !== '' && row.size !== '')
    .map(row => ({
      trade_id: row.trade_id || '',
      timestamp: row.open_time || '',
      system: row.system || '',
      symbol: row.symbol || '',
      side: row.side || '',
      order_type: 'TARGET EXIT',
      action: exitActionForOpenPosition(row.side),
      price: row.target,
      qty: row.size,
      status: 'working',
    }));
}

function parseClosedTradeRow(row) {
  const rawOpen = row[10] || '';
  const rawClose = row[11] || '';

  return {
    trade_id: row[0] || '',
    open_time: row[1] || '',
    close_time: row[2] || '',
    system: strategyFamilyLabelFromRaw(rawOpen, rawClose),
    symbol: row[3] || '',
    side: String(row[4] || '').toUpperCase(),
    entry: cleanNumber(row[5]),
    exit: cleanNumber(row[6]),
    size: cleanNumber(row[7]),
    result: cleanNumber(row[8]),
    event: row[9] || '',
    raw_open: rawOpen,
    raw_close: rawClose,
  };
}

async function getDashboardData() {
  const sheets = await getSheetsClient();

  if (!sheets) {
    throw new Error('Google Sheets client is not configured.');
  }

  const [openValues, pendingValues, closedValues] = await Promise.all([
    readSheet(sheets, OPEN_POSITIONS_SHEET, 'A:L'),
    readSheet(sheets, PENDING_SHEET, 'A:J'),
    readSheet(sheets, CLOSED_TRADES_SHEET, 'A:L'),
  ]);

  let openPositions = openValues
    .slice(1)
    .filter(row => row[0])
    .map(parseOpenPositionRow);

  openPositions = enrichOpenPositionsWithLiveQuotes(openPositions);

  const pendingOrders = pendingValues
    .slice(1)
    .filter(row => row[0])
    .map(parsePendingRow);

  const workingExitOrders = buildWorkingExitOrders(openPositions);
  const workingOrders = [...pendingOrders, ...workingExitOrders];

  const closedTradesAll = closedValues
    .slice(1)
    .filter(row => row[0])
    .map(parseClosedTradeRow)
    .filter(row => row.result !== '' && row.entry !== '' && row.exit !== '' && row.size !== '');

  closedTradesAll.sort((a, b) => String(b.close_time).localeCompare(String(a.close_time)));

  const today = nowNy().slice(0, 10);

  const openPnl = openPositions.reduce((sum, row) => sum + (cleanNumber(row.open_pnl) || 0), 0);
  const exposure = openPositions.reduce((sum, row) => sum + (cleanNumber(row.exposure) || 0), 0);
  const totalClosedPnl = closedTradesAll.reduce((sum, row) => sum + (cleanNumber(row.result) || 0), 0);

  const closedToday = closedTradesAll.filter(row => String(row.close_time || '').slice(0, 10) === today);
  const closedPnlToday = closedToday.reduce((sum, row) => sum + (cleanNumber(row.result) || 0), 0);

  const winners = closedTradesAll.filter(row => cleanNumber(row.result) > 0).length;
  const winRate = closedTradesAll.length > 0 ? (winners / closedTradesAll.length) * 100 : 0;

  return {
    updated_at: nowNy(),
    quote_status: quoteStatusForOpenPositions(openPositions),
    open_positions: openPositions,
    pending_orders: pendingOrders,
    working_orders: workingOrders,
    recent_closed_trades: closedTradesAll.slice(0, 20),
    summary: {
      open_count: openPositions.length,
      pending_count: workingOrders.length,
      open_pnl: Number(openPnl.toFixed(2)),
      closed_count_today: closedToday.length,
      closed_pnl_today: Number(closedPnlToday.toFixed(2)),
      total_closed_pnl: Number(totalClosedPnl.toFixed(2)),
      win_rate: Number(winRate.toFixed(2)),
      exposure: Number(exposure.toFixed(2)),
    },
  };
}


async function getOwnerDashboardData() {
  const data = await getDashboardData();
  const openPositions = enrichOpenPositionsForOwner(data.open_positions || []);
  const openPnl = openPositions.reduce((sum, row) => sum + (cleanNumber(row.open_pnl) || 0), 0);

  return {
    ...data,
    quote_status: ownerQuoteStatusForOpenPositions(openPositions),
    open_positions: openPositions,
    summary: {
      ...data.summary,
      open_pnl: Number(openPnl.toFixed(2)),
    },
  };
}

